// ── Element spec ──
// 6 carbon spheres → SphereGeometry(0.20) color #444444, chair positions
// 6 axial H spheres → SphereGeometry(0.13) color #cc2222, along ±z from carbons
// 6 equatorial H spheres → SphereGeometry(0.13) color #4aa3e0, fanning outward
// 6 C-C bonds → CylinderGeometry(0.05,0.05,len) color #bbbbbb
// 6 C-H axial bonds → CylinderGeometry(0.035,0.035,len) color #dddddd
// 6 C-H equatorial bonds → CylinderGeometry(0.035,0.035,len) color #dddddd
// C3 axis → dashed line along z, faint gray
// Labels: Axial (magenta), Equatorial (blue) with arrow lines

const molGroup = new THREE.Group();
scene.add(molGroup);

// ── Data structures ──
const carbons = [];
const axialHs = [];
const equatorialHs = [];
const ccBonds = [];
const chAxialBonds = [];
const chEqBonds = [];

const RING_R = 1.25;
const Z_UP = 0.30, Z_DOWN = -0.30;
const AXIAL_OFFSET = 0.95;
const EQ_DIST = 1.0;

// Carbon positions
for (let i = 0; i < 6; i++) {
  const theta = (i * 60) * Math.PI / 180;
  const isUp = (i % 2 === 0); // 0,120,240 are up
  const z = isUp ? Z_UP : Z_DOWN;
  const x = RING_R * Math.cos(theta);
  const y = RING_R * Math.sin(theta);
  carbons.push({ pos: new THREE.Vector3(x, y, z), theta, isUp, index: i });
}

// ── Materials ──
const carbonMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.4, metalness: 0.1 });
const axialMat = new THREE.MeshStandardMaterial({ color: 0xcc2222, roughness: 0.3, metalness: 0.05, transparent: true });
const eqMat = new THREE.MeshStandardMaterial({ color: 0x4aa3e0, roughness: 0.3, metalness: 0.05, transparent: true });
const ccBondMat = new THREE.MeshStandardMaterial({ color: 0xbbbbbb, roughness: 0.5 });
const chBondMat = new THREE.MeshStandardMaterial({ color: 0xdddddd, roughness: 0.5, transparent: true });

// ── Build carbon spheres ──
const carbonMeshes = [];
for (const c of carbons) {
  const geo = new THREE.SphereGeometry(0.20, 24, 24);
  const mesh = new THREE.Mesh(geo, carbonMat.clone());
  mesh.position.copy(c.pos);
  molGroup.add(mesh);
  carbonMeshes.push(mesh);
  registerInteractive(mesh, {
    title: `Carbon ${c.index + 1}`,
    body: `This carbon bears one axial H (red) and one equatorial H (blue). Click to highlight both.`,
    tooltip: `Carbon ${c.index + 1} — click to highlight its H atoms`
  });
}

// ── Build axial H spheres ──
const axialMeshes = [];
for (const c of carbons) {
  const dir = c.isUp ? 1 : -1;
  const hPos = c.pos.clone().add(new THREE.Vector3(0, 0, dir * AXIAL_OFFSET));
  const geo = new THREE.SphereGeometry(0.13, 20, 20);
  const mesh = new THREE.Mesh(geo, axialMat.clone());
  mesh.position.copy(hPos);
  molGroup.add(mesh);
  axialMeshes.push(mesh);
  axialHs.push({ mesh, carbon: c, pos: hPos });
}

// ── Build equatorial H spheres ──
const eqMeshes = [];
for (const c of carbons) {
  const sign = c.isUp ? 1 : -1;
  const dir = new THREE.Vector3(Math.cos(c.theta), Math.sin(c.theta), -0.35 * sign).normalize();
  const hPos = c.pos.clone().add(dir.clone().multiplyScalar(EQ_DIST));
  const geo = new THREE.SphereGeometry(0.13, 20, 20);
  const mesh = new THREE.Mesh(geo, eqMat.clone());
  mesh.position.copy(hPos);
  molGroup.add(mesh);
  eqMeshes.push(mesh);
  equatorialHs.push({ mesh, carbon: c, pos: hPos });
}

// ── Helper: create cylinder between two points ──
function makeBond(p1, p2, radius, mat) {
  const mid = p1.clone().add(p2).multiplyScalar(0.5);
  const dir = p2.clone().sub(p1);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(radius, radius, len, 8, 1);
  const mesh = new THREE.Mesh(geo, mat.clone());
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
