const axisMat = new THREE.LineDashedMaterial({ color: 0x999999, dashSize: 0.1, gapSize: 0.08, transparent: true, opacity: 0.5 });
const axisLine = new THREE.Line(axisGeo, axisMat);
axisLine.computeLineDistances();
molGroup.add(axisLine);

// ── Lighting ─
