addLabel('<span style="color:#cc00aa;font-weight:bold;">Axial</span>', axialTarget.clone().add(new THREE.Vector3(0.6, 0.6, 0.3)), { color: '#cc00aa', fontSize: '14px', bold: true });
// Arrow line for axial
const axArrowPts = [axialTarget.clone().add(new THREE.Vector3(0.5, 0.5, 0.25)), axialTarget.clone().add(new THREE.Vector3(0.05, 0.05, 0.02))];
const axArrowGeo = new THREE.BufferGeometry().setFromPoints(axArrowPts);
const axArrowMat = new THREE.LineBasicMaterial({ color: 0xcc00aa });
const axArrow = new THREE.Line(axArrowGeo, axArrowMat);
molGroup.add(axArrow);

// Equatorial label → points to equatorial H at carbon index 1 (60°)
const eqTarget = equatorialHs[1].pos.clone();
addLabel('<span style="color:#1a86d0;font-weight:bold;">Equatorial</span>', eqTarget.clone().add(new THREE.Vector3(0.5, 0.7, 0.3)), { color: '#1a86d0', fontSize: '14px', bold: true });
const eqArrowPts = [eqTarget.clone().add(new THREE.Vector3(0.4, 0.6, 0.25)), eqTarget.clone().add(new THREE.Vector3(0.05, 0.05, 0.02))];
const eqArrowGeo = new THREE.BufferGeometry().setFromPoints(eqArrowPts);
const eqArrowMat = new THREE.LineBasicMaterial({ color: 0x1a86d0 });
const eqArrow = new THREE.Line(eqArrowGeo, eqArrowMat);
molGroup.add(eqArrow);

// ── State management ──
let currentModel = 'ballstick';
let currentHVis = 'both';
let selectedCarbon = -1;

const BALLSTICK = { carbonR: 0.20, hR: 0.13, bondsVisible: true };
const SPACEFILL = { carbonR: 0.55, hR: 0.45, bondsVisible: false };

function applyModelStyle(style) {
  currentModel = style;
  const params = style === 'spacefill' ? SPACEFILL : BALLSTICK;

  for (const mesh of carbonMeshes) {
    mesh.geometry.dispose();
    mesh.geometry = new THREE.SphereGeometry(params.carbonR, 24, 24);
  }
  for (const mesh of axialMeshes) {
    mesh.geometry.dispose();
    mesh.geometry = new THREE.SphereGeometry(params.hR, 20, 20);
  }
  for (const mesh of eqMeshes) {
    mesh.geometry.dispose();
    mesh.geometry = new THREE.SphereGeometry(params.hR, 20, 20);
  }
  for (const bond of [...ccBonds, ...chAxialBonds, ...chEqBonds]) {
    bond.visible = params.bondsVisible;
  }
}

function applyHVisibility(vis) {
  currentHVis = vis;
  for (let i = 0; i < 6; i++) {
    const showAxial = vis === 'both' || vis === 'axial';
    const showEq = vis === 'both' || vis === 'equatorial';
    axialMeshes[i].visible = showAxial;
    chAxialBonds[i].visible = showAxial && currentModel === 'ballstick';
    eqMeshes[i].visible = showEq;
    chEqBonds[i].visible = showEq && currentModel === 'ballstick';
  }
}

function selectCarbon(idx) {
  selectedCarbon = idx;
  for (let i = 0; i < 6; i++) {
    const cMat = carbonMeshes[i].material;
    const aMat = axialMeshes[i].material;
    const eMat = eqMeshes[i].material;
    if (i === idx) {
      cMat.emissive.setHex(0x333300);
      aMat.emissive.setHex(0x660000);
      eMat.emissive.setHex(0x003366);
    } else {
      cMat.emissive.setHex(0x000000);
      aMat.emissive.setHex(0x000000);
      eMat.emissive.setHex(0x000000);
    }
  }
}

// ── UI wiring ──
document.getElementById('modelStyle').addEventListener('change', (e) => {
  applyModelStyle(e.target.value);
  applyHVisibility(currentHVis);
});

document.getElementById('hVisibility').addEventListener('change', (e) => {
  applyHVisibility(e.target.value);
});

// Carbon click via raycaster is already handled by registerInteractive
// We need to add onClick to each carbon
for (let i = 0; i < 6; i++) {
  const mesh = carbonMeshes[i];
  // Override the interactive info onClick
  const entry = _interactiveObjects.find(e => e.object === mesh);
  if (entry) {
    entry.info.onClick = () => { selectCarbon(i); };
  }
}

// ── Demo steps ──
const steps = [
  { title: "Both positions, ball-and-stick", narration: "Top-down the chair shows red axial H's clustered near the ring center and blue equatorial H's fanning outward, alternating around the hexagon.", state: { modelStyle: "ballstick", hVisibility: "both" } },
  { title: "Axial only", narration: "Hiding the blue leaves three red axial H's on one face pointing up and three on the opposite face pointing down — countable and alternating.", state: { modelStyle: "ballstick", hVisibility: "axial" } },
  { title: "Equatorial only", narration: "Hiding the red leaves six blue equatorial H's ringing the perimeter, again three per face in alternating order.", state: { modelStyle: "ballstick", hVisibility: "equatorial" } },
  { title: "Space-filling, both", narration: "In the packed model the same red-inner / blue-outer alternation appears, matching the textbook's left panel.", state: { modelStyle: "spacefill", hVisibility: "both" } },
  { title: "Select one carbon", narration: "Click a gray carbon: its single red axial and single blue equatorial H glow together, showing both positions live on that one atom.", state: { modelStyle: "ballstick", hVisibility: "both" } }
];

let currentStep = 0;

function goToStep(idx) {
  currentStep = Math.max(0, Math.min(idx, steps.length - 1));
  const step = steps[currentStep];
  document.getElementById('stepLabel').textContent = `Step ${currentStep + 1}/${steps.length}`;
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarr').textContent = step.narration;

  // Apply state
  document.getElementById('modelStyle').value = step.state.modelStyle;
  document.getElementById('hVisibility').value = step.state.hVisibility;
  applyModelStyle(step.state.modelStyle);
  applyHVisibility(step.state.hVisibility);

  if (currentStep === 4) {
    selectCarbon(0);
  } else {
    selectCarbon(-1);
  }
}

document.getElementById('btnPrev').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(currentStep + 1));

goToStep(0);

// ── Camera ─
setCameraView({
  projection: 'perspective',
  azimuthDeg: 0,
  elevationDeg: 90,
  rollDeg: 0,
  heightFraction: 0.7
});
// @FIGURE_CODE_END

