userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Model
  <select id="modelStyle">
    <option value="both" selected>Both (side-by-side)</option>
    <option value="ballstick">Ball-and-stick</option>
    <option value="spacefill">Space-filling</option>
  </select>
</label>
<label>Hydrogens shown
  <select id="hVisibility">
    <option value="both" selected>Both</option>
    <option value="axial">Axial only</option>
    <option value="equatorial">Equatorial only</option>
  </select>
</label>
<div id="stepControls" style="display:flex;gap:4px;align-items:center;">
  <button id="btnPrev">◀</button>
  <span id="stepLabel" style="font-size:10px;">Step 1/5</span>
  <button id="btnNext">▶</button>
</div>
<div id="stepTitle" style="font-size:11px;font-weight:bold;"></div>
<div id="stepNarr" style="font-size:10px;color:#555;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ──
// Ring in XZ plane, Y = axial (C3) direction → top-down (elev 90) shows hexagon
// 6 carbon spheres → SphereGeometry(0.20/0.55) #444444
// 6 axial H → SphereGeometry(0.13/0.45) #cc2222, along ±Y
// 6 equatorial H → SphereGeometry(0.13/0.45) #4aa3e0, radial in XZ with ∓Y tilt
// C-C bonds → CylinderGeometry(0.05) #bbbbbb
// C-H bonds → CylinderGeometry(0.035) #dddddd
// C3 axis → dashed line along Y
// Two panels: space-filling at x=-2.4, ball-and-stick at x=+2.4
// Labels: Axial (magenta), Equatorial (blue) with arrow lines

const RING_R = 1.25;
const PUCKER = 0.30;
const AXIAL_OFFSET = 0.95;
const EQ_DIST = 1.0;
const PANEL_OFFSET = 2.4;

// ── Carbon data (ring in XZ, puckering along Y) ──
const carbons = [];
for (let i = 0; i < 6; i++) {
  const theta = (i * 60) * Math.PI / 180;
  const isUp = (i % 2 === 0);
  const y = isUp ? PUCKER : -PUCKER;
  const x = RING_R * Math.cos(theta);
  const z = RING_R * Math.sin(theta);
  carbons.push({ pos: new THREE.Vector3(x, y, z), theta, isUp, index: i });
}

// ── Materials ──
const carbonMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.35, metalness: 0.1 });
const axialMat = new THREE.MeshStandardMaterial({ color: 0xcc2222, roughness: 0.25, metalness: 0.05 });
const eqMat = new THREE.MeshStandardMaterial({ color: 0x4aa3e0, roughness: 0.25, metalness: 0.05 });
const ccBondMat = new THREE.MeshStandardMaterial({ color: 0xbbbbbb, roughness: 0.5 });
const chBondMat = new THREE.MeshStandardMaterial({ color: 0xdddddd, roughness: 0.5 });

// ── Helper: cylinder between two points ──
function makeBond(p1, p2, radius, mat) {
  const mid = p1.clone().add(p2).multiplyScalar(0.5);
  const dir = p2.clone().sub(p1);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(radius, radius, len, 8, 1);
  const mesh = new THREE.Mesh(geo, mat.clone());
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

// ── Build a model group ──
function buildModel(offsetX, style) {
  const group = new THREE.Group();
  group.position.x = offsetX;
  scene.add(group);

  const isSpace = style === 'spacefill';
  const cR = isSpace ? 0.55 : 0.20;
  const hR = isSpace ? 0.45 : 0.13;
  const showBonds = !isSpace;

  const carbonMeshes = [];
  const axialMeshes = [];
  const eqMeshes = [];
  const ccBonds = [];
  const chAxBonds = [];
  const chEqBonds = [];

  // Carbons
  for (const c of carbons) {
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(cR, 24, 24), carbonMat.clone());
    mesh.position.copy(c.pos);
    group.add(mesh);
    carbonMeshes.push(mesh);
    if (!isSpace) {
      registerInteractive(mesh, {
        title: `Carbon ${c.index + 1}`,
        body: `This carbon bears one axial H (red, along the C3 axis) and one equatorial H (blue, fanning outward). Click to highlight both.`,
        tooltip: `Carbon ${c.index + 1} — click to highlight its H atoms`,
        onClick: () => selectCarbon(c.index)
      });
    }
  }

  // Axial H (along ±Y)
  for (const c of carbons) {
    const dir = c.isUp ? 1 : -1;
    const hPos = c.pos.clone().add(new THREE.Vector3(0, dir * AXIAL_OFFSET, 0));
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(hR, 20, 20), axialMat.clone());
    mesh.position.copy(hPos);
    group.add(mesh);
    axialMeshes.push(mesh);
    if (showBonds) {
      const bond = makeBond(c.pos, hPos, 0.035, chBondMat);
      group.add(bond);
      chAxBonds.push(bond);
    }
  }

  // Equatorial H (radial in XZ, slight ∓Y tilt)
  for (const c of carbons) {
    const sign = c.isUp ? 1 : -1;
    const dir = new THREE.Vector3(Math.cos(c.theta), -0.35 * sign, Math.sin(c.theta)).normalize();
    const hPos = c.pos.clone().add(dir.clone().multiplyScalar(EQ_DIST));
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(hR, 20, 20), eqMat.clone());
    mesh.position.copy(hPos);
    group.add(mesh);
    eqMeshes.push(mesh);
    if (showBonds) {
      const bond = makeBond(c.pos, hPos, 0.035, chBondMat);
      group.add(bond);
      chEqBonds.push(bond);
    }
  }

  // C-C bonds
  if (showBonds) {
    for (let i = 0; i < 6; i++) {
      const bond = makeBond(carbons[i].pos, carbons[(i + 1) % 6].pos, 0.05, ccBondMat);
      group.add(bond);
      ccBonds.push(bond);
    }
  }

  // C3 axis dashed line
  const axisPts = [new THREE.Vector3(0, -1.6, 0), new THREE.Vector3(0, 1.6, 0)];
  const axisGeo = new THREE.BufferGeometry().setFromPoints(axisPts);
  const axisMat = new THREE.LineDashedMaterial({ color: 0x999999, dashSize: 0.1, gapSize: 0.08, transparent: true, opacity: 0.4 });
  const axisLine = new THREE.Line(axisGeo, axisMat);
  axisLine.computeLineDistances();
  group.add(axisLine);

  return { group, carbonMeshes, axialMeshes, eqMeshes, ccBonds, chAxBonds, chEqBonds, style };
}

// ── Build both panels ──
const spaceModel = buildModel(-PANEL_OFFSET, 'spacefill');
const stickModel = buildModel(PANEL_OFFSET, 'ballstick');
const models = [spaceModel, stickModel];

// ── Lighting ──
const keyLight = new THREE.DirectionalLight(0xffffff, 1.4);
keyLight.position.set(0, 5, 2);
scene.add(keyLight);
const ambLight = new THREE.AmbientLight(0xffffff, 0.55);
scene.add(ambLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(-2, 2, -3);
scene.add(fillLight);

// ── Labels ──
// Axial label → points to axial H at carbon 2 (120°) on the space-filling model
const axTarget = spaceModel.axialMeshes[2].position.clone();
addLabel('<span style="color:#cc00aa;font-weight:bold;">Axial</span>',
  axTarget.clone().add(new THREE.Vector3(-0.8, 0.5, -0.5)),
  { color: '#cc00aa', fontSize: '14px', bold: true });
const axArrowPts = [
  axTarget.clone().add(new THREE.Vector3(-0.6, 0.4, -0.4)),
  axTarget.clone().add(new THREE.Vector3(-0.05, 0.05, -0.02))
];
const axArrowGeo = new THREE.BufferGeometry().setFromPoints(axArrowPts);
const axArrow = new THREE.Line(axArrowGeo, new THREE.LineBasicMaterial({ color: 0xcc00aa }));
scene.add(axArrow);

// Equatorial label → points to equatorial H at carbon 1 (60°) on the space-filling model
const eqTarget = spaceModel.eqMeshes[1].position.clone();
addLabel('<span style="color:#1a86d0;font-weight:bold;">Equatorial</span>',
  eqTarget.clone().add(new THREE.Vector3(-0.5, 0.8, 0.5)),
  { color: '#1a86d0', fontSize: '14px', bold: true });
const eqArrowPts = [
  eqTarget.clone().add(new THREE.Vector3(-0.4, 0.6, 0.4)),
  eqTarget.clone().add(new THREE.Vector3(-0.05, 0.05, 0.02))
];
const eqArrowGeo = new THREE.BufferGeometry().setFromPoints(eqArrowPts);
const eqArrow = new THREE.Line(eqArrowGeo, new THREE.LineBasicMaterial({ color: 0x1a86d0 }));
scene.add(eqArrow);

// ── State ──
let currentModel = 'both';
let currentHVis = 'both';
let selectedCarbon = -1;

function applyModelStyle(style) {
  currentModel = style;
  spaceModel.group.visible = (style === 'both' || style === 'spacefill');
  stickModel.group.visible = (style === 'both' || style === 'ballstick');
}

function applyHVisibility(vis) {
  currentHVis = vis;
  for (const model of models) {
    for (let i = 0; i < 6; i++) {
      const showAx = vis === 'both' || vis === 'axial';
      const showEq = vis === 'both' || vis === 'equatorial';
      model.axialMeshes[i].visible = showAx;
      model.eqMeshes[i].visible = showEq;
      if (model.chAxBonds[i]) model.chAxBonds[i].visible = showAx;
      if (model.chEqBonds[i]) model.chEqBonds[i].visible = showEq;
    }
  }
}

function selectCarbon(idx) {
  selectedCarbon = idx;
  for (const model of models) {
    for (let i = 0; i < 6; i++) {
      const cMat = model.carbonMeshes[i].material;
      const aMat = model.axialMeshes[i].material;
      const eMat = model.eqMeshes[i].material;
      if (i === idx) {
        cMat.emissive.setHex(0x222200);
        aMat.emissive.setHex(0x550000);
        eMat.emissive.setHex(0x002244);
      } else {
        cMat.emissive.setHex(0x000000);
        aMat.emissive.setHex(0x000000);
        eMat.emissive.setHex(0x000000);
      }
    }
  }
}

// ── UI wiring ──
document.getElementById('modelStyle').addEventListener('change', (e) => {
  applyModelStyle(e.target.value);
});
document.getElementById('hVisibility').addEventListener('change', (e) => {
  applyHVisibility(e.target.value);
});

// ── Demo steps ──
const steps = [
  { title: "Both positions, side-by-side", narration: "Top-down the chair shows red axial H's clustered near the ring center and blue equatorial H's fanning outward, alternating around the hexagon. Left: space-filling; right: ball-and-stick.", state: { modelStyle: "both", hVisibility: "both" } },
  { title: "Axial only", narration: "Hiding the blue leaves three red axial H's on one face pointing up and three on the opposite face pointing down — countable and alternating.", state: { modelStyle: "both", hVisibility: "axial" } },
  { title: "Equatorial only", narration: "Hiding the red leaves six blue equatorial H's ringing the perimeter, again three per face in alternating order.", state: { modelStyle: "both", hVisibility: "equatorial" } },
  { title: "Space-filling focus", narration: "In the packed model the same red-inner / blue-outer alternation appears, matching the textbook's left panel.", state: { modelStyle: "spacefill", hVisibility: "both" } },
  { title: "Select one carbon", narration: "Click a gray carbon: its single red axial and single blue equatorial H glow together, showing both positions live on that one atom.", state: { modelStyle: "ballstick", hVisibility: "both" } }
];

let currentStep = 0;

function goToStep(idx) {
  currentStep = Math.max(0, Math.min(idx, steps.length - 1));
  const step = steps[currentStep];
  document.getElementById('stepLabel').textContent = `Step ${currentStep + 1}/${steps.length}`;
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarr').textContent = step.narration;
  document.getElementById('modelStyle').value = step.state.modelStyle;
  document.getElementById('hVisibility').value = step.state.hVisibility;
  applyModelStyle(step.state.modelStyle);
  applyHVisibility(step.state.hVisibility);
  if (currentStep === 4) selectCarbon(0);
  else selectCarbon(-1);
}

document.getElementById('btnPrev').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(currentStep + 1));
goToStep(0);

// ── Camera: top-down along C3 axis (Y) ──
setCameraView({
  projection: 'perspective',
  azimuthDeg: 0,
  elevationDeg: 90,
  rollDeg: 0,
  heightFraction: 0.7
});
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

