keyLight.position.set(0, 5, 2);
scene.add(keyLight);
const ambLight = new THREE.AmbientLight(0xffffff, 0.55);
scene.add(ambLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(-2, 2, -3);
scene.add(fillLight);

// ── Labels ──
// Axial label → points to axial H at carbon 2 (120°) on the space-filling model
const axTarget = spaceModel.axialMeshes[2].position.clone();
