const axArrow = new THREE.Line(axArrowGeo, new THREE.LineBasicMaterial({ color: 0xcc00aa }));
scene.add(axArrow);

// Equatorial label → points to equatorial H at carbon 1 (60°) on the space-filling model
const eqTarget = spaceModel.eqMeshes[1].position.clone();
addLabel('<span style="color:#1a86d0;font-weight:bold;">Equatorial</span>',
  eqTarget.clone().add(new THREE.Vector3(-0.5, 0.8, 0.5)),
  { color: '#1a86d0', fontSize: '14px', bold: true });
const eqArrowPts = [
  eqTarget.clone().add(new THREE.Vector3(-0.4, 0.6, 0.4)),
  eqTarget.clone().add(new THREE.Vector3(-0.05, 0.05, 0.02))
];
const eqArrowGeo = new THREE.BufferGeometry().setFromPoints(eqArrowPts);
const eqArrow = new THREE.Line(eqArrowGeo, new THREE.LineBasicMaterial({ color: 0x1a86d0 }));
scene.add(eqArrow);

// ── State ──
let currentModel = 'both';
let currentHVis = 'both';
let selectedCarbon = -1;

function applyModelStyle(style) {
  currentModel = style;
  spaceModel.group.visible = (style === 'both' || style === 'spacefill');
  stickModel.group.visible = (style === 'both' || style === 'ballstick');
}

function applyHVisibility(vis) {
  currentHVis = vis;
  for (const model of models) {
    for (let i = 0; i < 6; i++) {
      const showAx = vis === 'both' || vis === 'axial';
      const showEq = vis === 'both' || vis === 'equatorial';
      model.axialMeshes[i].visible = showAx;
      model.eqMeshes[i].visible = showEq;
      if (model.chAxBonds[i]) model.chAxBonds[i].visible = showAx;
      if (model.chEqBonds[i]) model.chEqBonds[i].visible = showEq;
    }
  }
}

function selectCarbon(idx) {
  selectedCarbon = idx;
  for (const model of models) {
    for (let i = 0; i < 6; i++) {
      const cMat = model.carbonMeshes[i].material;
      const aMat = model.axialMeshes[i].material;
      const eMat = model.eqMeshes[i].material;
      if (i === idx) {
        cMat.emissive.setHex(0x222200);
        aMat.emissive.setHex(0x550000);
        eMat.emissive.setHex(0x002244);
      } else {
        cMat.emissive.setHex(0x000000);
        aMat.emissive.setHex(0x000000);
        eMat.emissive.setHex(0x000000);
      }
    }
  }
}

// ── UI wiring ──
document.getElementById('modelStyle').addEventListener('change', (e) => {
  applyModelStyle(e.target.value);
});
document.getElementById('hVisibility').addEventListener('change', (e) => {
  applyHVisibility(e.target.value);
});

// ── Demo steps ──
const steps = [
  { title: "Both positions, side-by-side", narration: "Top-down the chair shows red axial H's clustered near the ring center and blue equatorial H's fanning outward, alternating around the hexagon. Left: space-filling; right: ball-and-stick.", state: { modelStyle: "both", hVisibility: "both" } },
  { title: "Axial only", narration: "Hiding the blue leaves three red axial H's on one face pointing up and three on the opposite face pointing down — countable and alternating.", state: { modelStyle: "both", hVisibility: "axial" } },
  { title: "Equatorial only", narration: "Hiding the red leaves six blue equatorial H's ringing the perimeter, again three per face in alternating order.", state: { modelStyle: "both", hVisibility: "equatorial" } },
  { title: "Space-filling focus", narration: "In the packed model the same red-inner / blue-outer alternation appears, matching the textbook's left panel.", state: { modelStyle: "spacefill", hVisibility: "both" } },
  { title: "Select one carbon", narration: "Click a gray carbon: its single red axial and single blue equatorial H glow together, showing both positions live on that one atom.", state: { modelStyle: "ballstick", hVisibility: "both" } }
];

let currentStep = 0;

function goToStep(idx) {
  currentStep = Math.max(0, Math.min(idx, steps.length - 1));
  const step = steps[currentStep];
  document.getElementById('stepLabel').textContent = `Step ${currentStep + 1}/${steps.length}`;
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarr').textContent = step.narration;
  document.getElementById('modelStyle').value = step.state.modelStyle;
  document.getElementById('hVisibility').value = step.state.hVisibility;
  applyModelStyle(step.state.modelStyle);
  applyHVisibility(step.state.hVisibility);
