userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Model
  <select id="modelStyle">
    <option value="Ball-and-stick" selected>Ball-and-stick</option>
    <option value="Space-filling">Space-filling</option>
  </select>
</label>
<label>Hydrogens shown
  <select id="hVisibility">
    <option value="Both" selected>Both</option>
    <option value="Axial only">Axial only</option>
    <option value="Equatorial only">Equatorial only</option>
  </select>
</label>
<div id="stepControls" style="display:flex;gap:4px;align-items:center;">
  <button id="btnPrev">◀</button>
  <span id="stepLabel" style="font-size:10px;">Step 1/5</span>
  <button id="btnNext">▶</button>
</div>
<div id="stepTitle" style="font-size:11px;font-weight:bold;"></div>
<div id="stepNarr" style="font-size:10px;color:#555;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ──
// Ring in XY plane, Z = C3 axis → camera at (0,0,R) looking -Z shows hexagon face-on
// 6 carbon spheres → SphereGeometry(0.20/0.80) #444444
// 6 axial H → SphereGeometry(0.13/0.60) #cc2222, along ±Z
// 6 equatorial H → SphereGeometry(0.13/0.60) #4aa3e0, radial in XY with ∓Z tilt
// C-C bonds → CylinderGeometry(0.05) #bbbbbb
// C-H bonds → CylinderGeometry(0.035) #dddddd
// C3 axis → dashed line along Z from -1.6 to +1.6
// Labels: 'Axial' magenta #cc00aa 16px, 'Equatorial' blue #1a86d0 16px with arrow lines
// Single model group, morph between ball-and-stick and space-filling via scale lerp

const RING_R = 1.25;
const PUCKER = 0.30;
const AXIAL_OFFSET = 0.95;
const EQ_DIST = 1.0;
const BS_C_R = 0.20;
const BS_H_R = 0.13;
const SF_C_R = 0.80;
const SF_H_R = 0.60;

// ── Carbon positions (ring in XY, pucker along Z) ──
const carbons = [];
for (let i = 0; i < 6; i++) {
  const theta = (i * 60) * Math.PI / 180;
  const isUp = (i % 2 === 0);
  const z = isUp ? PUCKER : -PUCKER;
  carbons.push({
    pos: new THREE.Vector3(RING_R * Math.cos(theta), RING_R * Math.sin(theta), z),
    theta, isUp, index: i
  });
}

// ── Materials ─
const carbonMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.35, metalness: 0.1 });
const axialMat = new THREE.MeshStandardMaterial({ color: 0xcc2222, roughness: 0.25, metalness: 0.05 });
const eqMat = new THREE.MeshStandardMaterial({ color: 0x4aa3e0, roughness: 0.25, metalness: 0.05 });
const ccBondMat = new THREE.MeshStandardMaterial({ color: 0xbbbbbb, roughness: 0.5, transparent: true });
const chBondMat = new THREE.MeshStandardMaterial({ color: 0xdddddd, roughness: 0.5, transparent: true });

// ── Helper: cylinder between two points ──
function makeBond(p1, p2, radius, mat) {
  const mid = p1.clone().add(p2).multiplyScalar(0.5);
  const dir = p2.clone().sub(p1);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(radius, radius, len, 8, 1);
  const mesh = new THREE.Mesh(geo, mat.clone());
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

// ── Build the model ──
const modelGroup = new THREE.Group();
scene.add(modelGroup);

const carbonMeshes = [], axialMeshes = [], eqMeshes = [];
const ccBonds = [], chAxBonds = [], chEqBonds = [];

// Carbons
for (const c of carbons) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(BS_C_R, 24, 24), carbonMat.clone());
  mesh.position.copy(c.pos);
  modelGroup.add(mesh);
  carbonMeshes.push(mesh);
  registerInteractive(mesh, {
    title: `Carbon ${c.index + 1}`,
    body: `This carbon bears one axial H (red, along the C3 axis) and one equatorial H (blue, fanning outward). Click to highlight both.`,
    tooltip: `Carbon ${c.index + 1} — click to highlight its H atoms`,
    onClick: () => selectCarbon(c.index)
  });
}

// Axial H (along ±Z)
for (const c of carbons) {
  const sign = c.isUp ? 1 : -1;
  const hPos = c.pos.clone().add(new THREE.Vector3(0, 0, sign * AXIAL_OFFSET));
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(BS_H_R, 20, 20), axialMat.clone());
  mesh.position.copy(hPos);
  modelGroup.add(mesh);
  axialMeshes.push(mesh);
  const bond = makeBond(c.pos, hPos, 0.035, chBondMat);
  modelGroup.add(bond);
  chAxBonds.push(bond);
}

// Equatorial H (radial in XY, slight ∓Z tilt)
for (const c of carbons) {
  const sign = c.isUp ? 1 : -1;
  const dir = new THREE.Vector3(Math.cos(c.theta), Math.sin(c.theta), -0.35 * sign).normalize();
  const hPos = c.pos.clone().add(dir.clone().multiplyScalar(EQ_DIST));
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(BS_H_R, 20, 20), eqMat.clone());
  mesh.position.copy(hPos);
  modelGroup.add(mesh);
  eqMeshes.push(mesh);
  const bond = makeBond(c.pos, hPos, 0.035, chBondMat);
  modelGroup.add(bond);
  chEqBonds.push(bond);
}

// C-C bonds
for (let i = 0; i < 6; i++) {
  const bond = makeBond(carbons[i].pos, carbons[(i + 1) % 6].pos, 0.05, ccBondMat);
  modelGroup.add(bond);
  ccBonds.push(bond);
}

// C3 axis dashed line along Z
const axisGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, -1.6), new THREE.Vector3(0, 0, 1.6)
]);
const axisLine = new THREE.Line(axisGeo, new THREE.LineDashedMaterial({
  color: 0x999999, dashSize: 0.1, gapSize: 0.08, transparent: true, opacity: 0.4
}));
axisLine.computeLineDistances();
modelGroup.add(axisLine);

// ── Lighting ──
const keyLight = new THREE.DirectionalLight(0xffffff, 1.4);
keyLight.position.set(2, 3, 5);
scene.add(keyLight);
const ambLight = new THREE.AmbientLight(0xffffff, 0.55);
scene.add(ambLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(-2, -1, 3);
scene.add(fillLight);

// ── Morph state ──
let morphT = 0; // 0 = ball-and-stick, 1 = space-filling
let currentHVis = 'Both';
let selectedCarbon = -1;

function updateMorph() {
  const cScale = THREE.MathUtils.lerp(1, SF_C_R / BS_C_R, morphT);
  const hScale = THREE.MathUtils.lerp(1, SF_H_R / BS_H_R, morphT);
  const bondOpacity = 1 - morphT;

  for (const m of carbonMeshes) m.scale.setScalar(cScale);
  for (const m of axialMeshes) m.scale.setScalar(hScale);
  for (const m of eqMeshes) m.scale.setScalar(hScale);
  for (const b of ccBonds) { b.material.opacity = bondOpacity; b.visible = bondOpacity > 0.01; }
  for (const b of chAxBonds) { b.material.opacity = bondOpacity; b.visible = bondOpacity > 0.01 && (currentHVis === 'Both' || currentHVis === 'Axial only'); }
  for (const b of chEqBonds) { b.material.opacity = bondOpacity; b.visible = bondOpacity > 0.01 && (currentHVis === 'Both' || currentHVis === 'Equatorial only'); }
}

function animateMorph(target) {
  const start = morphT;
  const startTime = performance.now();
  const duration = 400;
  function step() {
    const elapsed = performance.now() - startTime;
    const t = Math.min(1, elapsed / duration);
    const eased = t * t * (3 - 2 * t);
    morphT = start + (target - start) * eased;
    updateMorph();
    if (t < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

// ── Set camera AFTER geometry, frame for space-filling (max) bounds ──
// Temporarily set to space-filling to measure max bounds
morphT = 1;
updateMorph();

setCameraView({
  projection: 'perspective',
  azimuthDeg: 90,
  elevationDeg: 0,
  rollDeg: 0,
  heightFraction: 0.65
});

// Back to ball-and-stick default
morphT = 0;
updateMorph();

// ── Labels ──
// Axial label → points to axial H at carbon 2 (120°, up-carbon)
const axTargetPos = axialMeshes[2].position.clone(); // (-0.625, 1.083, 1.25)
addLabel('<span style="color:#cc00aa;font-weight:bold;">Axial</span>',
  new THREE.Vector3(-2.0, 2.0, 1.5),
  { color: '#cc00aa', fontSize: '16px', bold: true });

// Axial arrow line (in front at Z=1.5)
const axArrowPts = [
  new THREE.Vector3(-1.7, 1.7, 1.5),
  new THREE.Vector3(axTargetPos.x - 0.15, axTargetPos.y - 0.15, 1.5)
];
const axArrowGeo = new THREE.BufferGeometry().setFromPoints(axArrowPts);
const axArrow = new THREE.Line(axArrowGeo, new THREE.LineBasicMaterial({ color: 0xcc00aa }));
scene.add(axArrow);

// Equatorial label → points to equatorial H at carbon 1 (60°, down-carbon)
const eqTargetPos = eqMeshes[1].position.clone(); // ~(1.10, 1.90, 0.03)
addLabel('<span style="color:#1a86d0;font-weight:bold;">Equatorial</span>',
  new THREE.Vector3(0.3, 3.0, 1.5),
  { color: '#1a86d0', fontSize: '16px', bold: true });

// Equatorial arrow line
const eqArrowPts = [
  new THREE.Vector3(0.6, 2.7, 1.5),
  new THREE.Vector3(eqTargetPos.x - 0.1, eqTargetPos.y - 0.15, 1.5)
];
const eqArrowGeo = new THREE.BufferGeometry().setFromPoints(eqArrowPts);
const eqArrow = new THREE.Line(eqArrowGeo, new THREE.LineBasicMaterial({ color: 0x1a86d0 }));
scene.add(eqArrow);

// ── Interaction functions ──
function applyModelStyle(style) {
  const target = (style === 'Space-filling') ? 1 : 0;
  animateMorph(target);
}

function applyHVisibility(vis) {
  currentHVis = vis;
  const showAx = vis === 'Both' || vis === 'Axial only';
  const showEq = vis === 'Both' || vis === 'Equatorial only';
  for (let i = 0; i < 6; i++) {
    axialMeshes[i].visible = showAx;
    eqMeshes[i].visible = showEq;
    chAxBonds[i].visible = showAx && morphT < 0.99;
    chEqBonds[i].visible = showEq && morphT < 0.99;
  }
}

function selectCarbon(idx) {
  selectedCarbon = idx;
  for (let i = 0; i < 6; i++) {
    const sel = (i === idx);
    carbonMeshes[i].material.emissive.setHex(sel ? 0x333300 : 0x000000);
    axialMeshes[i].material.emissive.setHex(sel ? 0x660000 : 0x000000);
    eqMeshes[i].material.emissive.setHex(sel ? 0x003355 : 0x000000);
  }
}

// ── UI wiring ──
document.getElementById('modelStyle').addEventListener('change', (e) => {
  applyModelStyle(e.target.value);
});
document.getElementById('hVisibility').addEventListener('change', (e) => {
  applyHVisibility(e.target.value);
});

// ── Demo steps ──
const steps = [
  { title: "Both positions, ball-and-stick", narration: "Top-down the chair shows red axial H's clustered near the ring center and blue equatorial H's fanning outward, alternating around the hexagon.", state: { modelStyle: "Ball-and-stick", hVisibility: "Both" } },
  { title: "Axial only", narration: "Hiding the blue leaves three red axial H's on one face pointing up and three on the opposite face pointing down — countable and alternating.", state: { modelStyle: "Ball-and-stick", hVisibility: "Axial only" } },
  { title: "Equatorial only", narration: "Hiding the red leaves six blue equatorial H's ringing the perimeter, again three per face in alternating order.", state: { modelStyle: "Ball-and-stick", hVisibility: "Equatorial only" } },
  { title: "Space-filling, both", narration: "In the packed model the same red-inner / blue-outer alternation appears, matching the textbook's left panel.", state: { modelStyle: "Space-filling", hVisibility: "Both" } },
  { title: "Select one carbon", narration: "Click a gray carbon: its single red axial and single blue equatorial H glow together, showing both positions live on that one atom.", state: { modelStyle: "Ball-and-stick", hVisibility: "Both" } }
];

let currentStep = 0;

function goToStep(idx) {
  currentStep = Math.max(0, Math.min(idx, steps.length - 1));
  const step = steps[currentStep];
  document.getElementById('stepLabel').textContent = `Step ${currentStep + 1}/${steps.length}`;
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarr').textContent = step.narration;
  document.getElementById('modelStyle').value = step.state.modelStyle;
  document.getElementById('hVisibility').value = step.state.hVisibility;
  applyModelStyle(step.state.modelStyle);
  applyHVisibility(step.state.hVisibility);
  if (currentStep === 4) selectCarbon(0);
  else selectCarbon(-1);
}

document.getElementById('btnPrev').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(currentStep + 1));
goToStep(0);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
